{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE maplemonk.Banana_club_product_perform_factitems AS select order_date, image_link, product_name, marketplace, date_bucket, ROUND(SAFE_DIVIDE( SUM(IFNULL(selling_price,0)) - SUM(IFNULL(cost,0)), NULLIF(SUM(IFNULL(selling_price,0)),0))*100,2) AS Gross_Profit, sum(selling_price) selling_price, sum(quantity) quantity, sum(returned_quantity) returned_quantity, max(current_inventory) current_inventory, sum(cost) cost, sum(spend) spend, sum(ad_impressions) ad_impressions, sum(ad_clicks) ad_clicks, sum(ad_conversions) ad_conversions, sum(ad_sales) ad_sales from(SELECT sc.marketplace AS final_marketplace, CASE WHEN UPPER(sc.marketplace) = \'WEBSITE\' THEN \'WEBSITE\' WHEN UPPER(sc.marketplace) IN (\'MYNTRAPPMP\',\'MYNTRAPPMP_EMIZA\') THEN \'MYNTRA\' WHEN UPPER(sc.marketplace) LIKE \'%AJIO%\' OR UPPER(sc.marketplace) LIKE \'%FLIPKART%\' THEN \'OTHERS\' END AS marketplace, coalesce(sc.channel_mapped,mc.marketing_channel) channel, sc.sku, sc.Order_Date, CASE WHEN DATE(sc.order_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 7 DAY) THEN \'<=7D\' WHEN DATE(sc.order_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 30 DAY) THEN \'8-30D\' WHEN DATE(sc.order_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 60 DAY) THEN \'31-60D\' WHEN DATE(sc.order_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 90 DAY) THEN \'61-90D\' ELSE \'>90D\' END AS date_bucket, COALESCE(sr.QUANTITY, mr.QUANTITY, sc.QUANTITY) AS Quantity, COALESCE(sc.TAX, mr.TAX) AS Tax, sc.SELLING_PRICE AS Selling_price, UPPER(COALESCE(inv.name, sc.final_product_name)) AS Product_name, sc.city, sc.state, COALESCE(sr.return_reason, mr.return_reason) AS Return_reason, COALESCE(sr.returned_quantity, mr.returned_quantity, sc.returned_quantity) AS returned_quantity, cc.cost, inv.inventory AS current_inventory, COALESCE(inv.image_link, sc.image_link) AS image_link, safe_divide(coalesce(spend,0), count(1) over (partition by coalesce(sc.order_date,mc.date), coalesce(sc.channel_mapped, mc.marketing_channel), coalesce(sc.marketplace,mc.marketplace))) spend, coalesce(ad_impressions,0) ad_impressions, coalesce(ad_clicks,0) ad_clicks, coalesce(ad_conversions,0) ad_conversions, safe_divide(coalesce(ad_sales,0),count(1) over (partition by coalesce(sc.order_date,mc.date), coalesce(sc.channel_mapped, mc.marketing_channel), coalesce(sc.marketplace,mc.marketplace))) ad_sales from (select *, case when lower(channel) like any (\'%facebook%\',\'%fb%\',\'%meta%\',\'%insta%\',\'%ig%\') then \'FACEBOOK\' when lower(channel) like any (\'%google%\') then \'GOOGLE\' else upper(channel) end channel_mapped from maplemonk.bananaclub_sales_consolidated ) sc LEFT JOIN ( SELECT REPLACE(order_name, \'#\', \'\') AS order_name, sku, CAST(order_timestamp AS DATE) AS Order_Date, sales_quantity AS QUANTITY, name AS PRODUCT_NAME_FINAL, city, state, return_quantity AS returned_quantity, cancelled_quantity, customer_reason_label AS return_reason FROM maplemonk.shopify_return_exchange QUALIFY ROW_NUMBER() OVER( PARTITION BY order_name, sku, CAST(order_timestamp AS DATE) ORDER BY order_timestamp DESC ) = 1 ) sr ON LOWER(REPLACE(sc.reference_code, \'#\', \'\')) = LOWER(REPLACE(sr.order_name, \'#\', \'\')) AND LOWER(sc.sku) = LOWER(sr.sku) LEFT JOIN ( SELECT sellerOrderId, sku, CAST(created_on AS DATE) AS Order_Date, created_on AS Order_Time, quantity, Taxable AS TAX, final_amount AS SELLING_PRICE, PRODUCT_NAME AS PRODUCT_NAME_FINAL, city, return_quantity AS returned_quantity, return_reason FROM MapleMonk.BananaClub_db_Myntra_Master QUALIFY ROW_NUMBER() OVER( PARTITION BY sellerOrderId, sku, CAST(created_on AS DATE) ORDER BY created_on DESC ) = 1 ) mr ON DATE(sc.order_date) = DATE(mr.Order_Date) AND LOWER(REPLACE(sc.reference_code, \'#\', \'\')) = LOWER(REPLACE(mr.sellerOrderId, \'#\', \'\')) AND LOWER(sc.sku) = LOWER(mr.sku) LEFT JOIN ( SELECT sku_code, CAST(cost AS INT64) AS cost FROM maplemonk.banana_club_Google_sheet_cost ) cc ON LOWER(sc.sku) = lower(cc.sku_code) LEFT JOIN (select date,name,image_link,inventory from( SELECT date, name, image_link, SUM(inventory) AS inventory FROM maplemonk.daily_inventory where inventory>0 GROUP BY 1,2,3) ) inv ON UPPER(sc.final_product_name) = UPPER(inv.name) full outer join (select date ,case when lower(channel) like any (\'%facebook%\', \'%google%\') then \'WEBSITE\' when lower(channel) like any (\'%amazon%\') then \'AMAZON\' when lower(channel) like \'%flipkart%\' then \'FLIPKART\' when lower(channel) like \'%myntra%\' then \'MYNTRA\' else upper(channel) end as Marketplace ,upper(channel) marketing_Channel ,sum(ifnull(spend,0)) as spend ,sum(ifnull(impressions,0)) as ad_impressions ,sum(ifnull(clicks,0)) as ad_clicks ,sum(ifnull(conversions,0)) as ad_conversions ,sum(ifnull(conversion_value,0)) as ad_sales from maplemonk.BananaClub_MARKETING_CONSOLIDATED where channel in (\'GOOGLE\',\'FACEBOOK\') group by 1,2,3 ) mc on date(sc.order_Date) = date(MC.date) and lower(SC.channel_mapped)=lower(MC.marketing_channel) and upper(sc.marketplace) = upper(mc.marketplace)) group by 1,2,3,4,5;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            